static DWORD WINAPI thread_body(LPVOID parameter)
{
    LAB05_THREAD_PARAM *param = (LAB05_THREAD_PARAM *)parameter;
    printf("=== Lab-05c: поток %d, PID %lu, TID %lu, приоритет %s ===\n",
           param->index,
